		_matter_units[m] = int(_matter_units[m]) - n
		if mix[m] == 0:
			mix.erase(m)
		units -= n
	if mix.is_empty():
		_matter_nodes.erase(g)
	if units > 0:
		var m := int(_beds.get(g, 0))
		out[m] = int(out.get(m, 0)) + units
		_map_units[m] = int(_map_units.get(m, 0)) + units
	return out


func _matter_add(i: int, mix: Dictionary) -> void:
	var g := _global_node(i)
	var stock: Dictionary = _matter_nodes.get(g, {})
	for m: int in mix:
		var n := int(mix[m])
		stock[m] = int(stock.get(m, 0)) + n
		_matter_units[m] = int(_matter_units.get(m, 0)) + n
